def solve(I, full=True):
    I=np.array(I); H,W=I.shape
    bg=int(np.bincount(I.flatten()).argmax())
    lab,n=scipy.ndimage.label(I!=bg)
    sizes={int(len(np.argwhere(lab==v))):None for v in range(1,n+1)}
    # find big component correctly: label counts per value; pick color with most cells not bg
    from collections import Counter
    cnt=Counter(int(x) for x in I.flatten() if x!=bg)
    pat=cnt.most_common(1)[0][0]
    rs,cs=np.where(I==pat)
    r0,c0=rs.min(),cs.min()
    hh=rs.max()-r0+1; ww=cs.max()-c0+1
    blk=[[int(I[r][c]) for c in range(c0,c0+ww)] for r in range(r0,r0+hh)]
    O=I.copy()
    for ar,ac in zip(*np.where((I!=bg)&(I!=pat))):
        tr=ar-((hh-1)//2); tc=ac-((ww-1)//2)
        for i in range(hh):
            for j in range(ww):
                rr,cc=tr+i,tc+j
                if 0<=rr<H and 0<=cc<W:
                    if full or blk[i][j]!=bg: O[rr][cc]=blk[i][j]
    return O.tolist()

