    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(I):
    Hh,Ww=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    seen=[[False]*Ww for _ in range(Hh)]; cs=[]
    for i in range(Hh):
        for j in range(Ww):
            if I[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<Hh and 0<=y<Ww and I[x][y]!=bg and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                cs.append(comp)
    pat=max(cs,key=len); singles=[c for c in cs if len(c)==1]
    cnt=Counter(p for c in pat for p in [I[c[0]][c[1]]])
    ucol=min(cnt, key=lambda c: cnt[c])
    mi,mj=next((p for p in pat if I[p[0]][p[1]]==ucol))
    rel_r=(mi-min(p[0] for p in pat)); rel_c=(mj-min(p[1] for p in pat))
    out=[r[:] for r in I]
    for c in singles:
        a,b=c[0]
        # clear marker cell first? try without clearing then with clearing
        for rr in range(min(p[0] for p in pat), max(p[0] for p in pat)+1):
            for cc_ in range(min(p[1] for p in pat), max(p[1] for p in pat)+1):
                x,y=a-(mi-min(p[0] for p in pat))+rr, b-(mj-min(p[1] for p in pat))+cc_
                if 0<=x<Hh and 0<=y<Ww: out[x][y]=I[rr][cc_]
    return out
