def stamp_regions(I,O):
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    diffs=[(r,c) for r in range(len(O)) for c in range(len(O[0])) if O[r][c]!=I[r][c]]
    # cluster diffs into rectangles
    seen=set(); regs=[]
    for p in sorted(diffs):
        if p in seen: continue
        r0=c0=r=p[0]; c0_=c=p[1]; cells={p}
        while True:
            ex,ey=r-1,c0_-1; er,ec=r+1,c0_+1
            while ex>=0 and (ex,er) not in cells: pass
        # simpler: flood fill over diffs with adjacency
            break
        # do proper BFS later
    return diffs,bg
for k in ('Demo pair 4','Demo pair 5','Demo pair 6'):
    I=G[k+' input']; O=G[k+' output']
    diffs=[(r,c) for r in range(len(O)) for c in range(len(O[0])) if O[r][c]!=I[r][c]]
    print('===',k,'ndiff',len(diffs))
    # connected components of diffs (adjacent)
    seen=set(); comps=[]
    for p in sorted(diffs):
        if p in seen: continue
        st=[p]; cc_=[]
        while st:
            a,b=st.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); cc_.append((a,b))
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    n=(a+dx,b+dy)
                    if n in diffs and n not in seen: st.append(n)
        comps.append(sorted(cc_))
    for comp in comps[:3]:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        print('  rect',(min(rs),min(cs),max(rs),max(cs),'n=',len(comp)))

