                    rr,cc_=ti+i,tj+j
                    if 0<=rr<Hh and 0<=cc_<Ww: out[rr][cc_]=P[i][j]
    elif anchor_mode=='unique':
        cnt=Counter(v for row in P for v in row)
        uniq=[col for col,n in cnt.items() if n==1]
        if len(uniq)!=1: raise ValueError('multiple uniques')
